import fs from 'node:fs';import path from 'node:path';import readline from 'node:readline';import {createHash} from 'node:crypto';import {createRealtimeSpreadEconomics,REALTIME_ECONOMICS_POLICIES} from '../live-paper/realtime-spread-economics.mjs';
const root=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),start='realtime-2026-10-04T21-59',through='realtime-2026-10-05T16-15',out='data/realtime-spread-economics-20261005.json';
const files=fs.readdirSync(root).filter(x=>x.endsWith('.jsonl')&&x>=start&&x<=through+'\uffff'&&x.startsWith('realtime-')).sort(),sources=[];const study=createRealtimeSpreadEconomics(),started=performance.now();let rows=0;
fs.writeFileSync('data/realtime-spread-economics-policy-20261005.json',JSON.stringify({frozenAt:new Date().toISOString(),policies:REALTIME_ECONOMICS_POLICIES,files,mode:'development_diagnostic_no_profit_claim'},null,2)+'\n',{flag:'wx'});
for(const file of files){const full=path.join(root,file),size=fs.statSync(full).size,h=createHash('sha256');const stream=fs.createReadStream(full);stream.on('data',b=>h.update(b));const lines=readline.createInterface({input:stream,crlfDelay:Infinity});let count=0;for await(const line of lines){if(!line)continue;study.consume(JSON.parse(line),{sourceId:file});count++;rows++;}if(fs.statSync(full).size!==size)throw Error('SOURCE_CHANGED');sources.push({file,bytes:size,sha256:h.digest('hex'),rows:count});console.log(JSON.stringify({file,rows:count,elapsedMs:Math.round(performance.now()-started)}));}
const r={...study.report(),sources,elapsedMs:performance.now()-started,rows};fs.writeFileSync(out,JSON.stringify(r,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({...r,policies:r.policies.map(({outcomes,...s})=>s),sources:undefined},null,2));
